code.cpp:
class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        if (source == target) return 0;

        unordered_map<int, vector<int>> stopToBuses;
        for (int i = 0; i < (int)routes.size(); i++) {
            for (int s : routes[i]) {
                stopToBuses[s].push_back(i);
            }
        }

        if (stopToBuses.find(source) == stopToBuses.end() || 
            stopToBuses.find(target) == stopToBuses.end()) return -1;

        vector<char> busVisited(routes.size(), 0);
        unordered_set<int> stopVisited;
        queue<int> q;
        q.push(source);
        stopVisited.insert(source);
        int buses = 0;

        while (!q.empty()) {
            int sz = q.size();
            buses++;
            for (int i = 0; i < sz; i++) {
                int stop = q.front(); q.pop();
                for (int bus : stopToBuses[stop]) {
                    if (busVisited[bus]) continue;
                    busVisited[bus] = 1;
                    for (int nextStop : routes[bus]) {
                        if (nextStop == target) return buses;
                        if (stopVisited.find(nextStop) == stopVisited.end()) {
                            stopVisited.insert(nextStop);
                            q.push(nextStop);
                        }
                    }
                }
            }
        }
        return -1;
    }
};
